// Throwaway: exercises the behaviour implied by TestResponseWriterStatusCode.
func TestZZTmpResponseWriterStatusCode(t *testing.T) {
	// 1. WriteHeader before anything is written: status is remembered, nothing flushed.
	rec := httptest.NewRecorder()
	w := &responseWriter{}
	w.reset(rec)
	if w.Status() != http.StatusOK || w.Written() || w.Size() != -1 {
		t.Fatalf("fresh: status=%d written=%v size=%d", w.Status(), w.Written(), w.Size())
	}
	w.WriteHeader(http.StatusCreated)
	if w.Status() != http.StatusCreated || w.Written() || rec.Code != http.StatusOK {
		t.Fatalf("after WriteHeader(201): status=%d written=%v rec.Code=%d", w.Status(), w.Written(), rec.Code)
	}

	// 2. WriteHeaderNow flushes the remembered status and is idempotent.
	w.WriteHeaderNow()
	if !w.Written() || w.Size() != 0 || rec.Code != http.StatusCreated {
		t.Fatalf("after WriteHeaderNow: written=%v size=%d rec.Code=%d", w.Written(), w.Size(), rec.Code)
	}
	w.WriteHeaderNow()
	if w.Size() != 0 || rec.Code != http.StatusCreated {
		t.Fatalf("WriteHeaderNow not idempotent: size=%d rec.Code=%d", w.Size(), rec.Code)
	}

	// 3. A second WriteHeader with a different code must NOT change Status()
	//    once the header has been written to the client.
	w.WriteHeader(http.StatusInternalServerError)
	if w.Status() != http.StatusCreated {
		t.Errorf("status overwritten after headers written: got %d want %d", w.Status(), http.StatusCreated)
	}
	if rec.Code != http.StatusCreated {
		t.Errorf("recorder code changed: got %d want %d", rec.Code, http.StatusCreated)
	}

	// 4. Writing a body without calling WriteHeader uses 200 and counts bytes.
	rec2 := httptest.NewRecorder()
	w2 := &responseWriter{}
	w2.reset(rec2)
	n, err := w2.Write([]byte("hola"))
	if err != nil || n != 4 {
		t.Fatalf("Write: n=%d err=%v", n, err)
	}
	if w2.Status() != http.StatusOK || w2.Size() != 4 || !w2.Written() || rec2.Code != http.StatusOK {
		t.Fatalf("after Write: status=%d size=%d written=%v rec.Code=%d", w2.Status(), w2.Size(), w2.Written(), rec2.Code)
	}
	// status still cannot be changed after the implicit header write
	w2.WriteHeader(http.StatusTeapot)
	if w2.Status() != http.StatusOK {
		t.Errorf("status overwritten after implicit write: got %d want 200", w2.Status())
	}

	// 5. WriteString path.
	rec3 := httptest.NewRecorder()
	w3 := &responseWriter{}
	w3.reset(rec3)
	w3.WriteHeader(http.StatusAccepted)
	if _, err := w3.WriteString("hi"); err != nil {
		t.Fatal(err)
	}
	if w3.Status() != http.StatusAccepted || w3.Size() != 2 || rec3.Code != http.StatusAccepted {
		t.Fatalf("WriteString: status=%d size=%d rec.Code=%d", w3.Status(), w3.Size(), rec3.Code)
	}
	w3.WriteHeader(http.StatusBadGateway)
	if w3.Status() != http.StatusAccepted {
		t.Errorf("status overwritten after WriteString: got %d want 202", w3.Status())
	}
}

