// substitute params with concrete values
func concretize(route string) string {
	var b strings.Builder
	segs := strings.Split(route, "/")
	for i, s := range segs {
		if i > 0 {
			b.WriteString("/")
		}
		if strings.HasPrefix(s, ":") {
			b.WriteString("v" + s[1:])
		} else if strings.HasPrefix(s, "*") {
			b.WriteString("v" + s[1:])
		} else {
			b.WriteString(s)
		}
	}
	return b.String()
}

