// matchPattern reports whether pattern (gin route) matches path, and returns
// the expected param values.
func matchPattern(pattern, path string) (map[string]string, bool) {
	ps := strings.Split(pattern, "/")
	xs := strings.Split(path, "/")
	out := map[string]string{}
	i := 0
	for ; i < len(ps); i++ {
		p := ps[i]
		if strings.HasPrefix(p, "*") {
			// catchAll: rest of path including leading slash
			rest := strings.Join(xs[i:], "/")
			out[p[1:]] = "/" + rest
			return out, true
		}
		if i >= len(xs) {
			return nil, false
		}
		if strings.HasPrefix(p, ":") {
			out[p[1:]] = xs[i]
			continue
		}
		if p != xs[i] {
			return nil, false
		}
	}
	if i != len(xs) {
		return nil, false
	}
	return out, true
}

